CREATE OR REPLACE FUNCTION public.trg_wallet_return()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status in ('rejected', 'cancelled') and old.status not in ('rejected', 'cancelled')
     and coalesce(new.wallet_used, 0) > 0 and new.wallet_returned_at is null then
    insert into wallet_entries(user_id, amount, kind, order_id) values (new.customer_id, new.wallet_used, 'return', new.id)
    on conflict (order_id) where kind = 'return' do nothing;
    new.wallet_returned_at := now();
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.audit_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n jsonb; v_o jsonb; v_d jsonb := '{}'::jsonb; v_k text; v_id text;
begin
  if tg_op = 'INSERT' then v_n := to_jsonb(new); v_id := v_n->>coalesce(tg_argv[0], 'id');
    insert into audit_log(user_id, action, table_name, row_id, details) values (auth.uid(), 'INSERT', tg_table_name, v_id, '{}'::jsonb);
    return new;
  elsif tg_op = 'DELETE' then v_o := to_jsonb(old); v_id := v_o->>coalesce(tg_argv[0], 'id');
    insert into audit_log(user_id, action, table_name, row_id, details) values (auth.uid(), 'DELETE', tg_table_name, v_id, '{}'::jsonb);
    return old;
  end if;
  v_n := to_jsonb(new); v_o := to_jsonb(old); v_id := v_n->>coalesce(tg_argv[0], 'id');
  foreach v_k in array tg_argv[1:] loop
    if (v_n->v_k) is distinct from (v_o->v_k) then v_d := v_d || jsonb_build_object(v_k, jsonb_build_object('from', v_o->v_k, 'to', v_n->v_k)); end if;
  end loop;
  if v_d <> '{}'::jsonb then
    insert into audit_log(user_id, action, table_name, row_id, details) values (auth.uid(), 'UPDATE', tg_table_name, v_id, v_d);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.log_order_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    insert into order_events(order_id, kind) values (new.id, 'pending');
  else
    if new.status is distinct from old.status then
      insert into order_events(order_id, kind) values (new.id, new.status::text);
    end if;
    if old.driver_id is null and new.driver_id is not null then
      insert into order_events(order_id, kind) values (new.id, 'driver_assigned');
    end if;
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION pilot_private.guard_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c pilot_private.config;local_time timestamp;minute_n int;active_n int;daily_n int;begin
 select *into c from pilot_private.config where id;
 if tg_op='UPDATE'then
  if new.driver_id is distinct from old.driver_id and new.driver_id is not null and exists(select 1 from pilot_private.admissions where order_id=old.id)and not pilot_private.driver_allowed(new.driver_id)then raise exception'pilot_driver_not_invited';end if;
  return new;
 end if;
 if c.paused or c.value is null then raise exception'pilot_paused';end if;
 if not(c.value->'customers'?new.customer_id::text)or not(c.value->'stores'?new.store_id::text)then raise exception'pilot_not_invited';end if;
 if now()<(c.value->>'valid_from')::timestamptz or now()>=(c.value->>'valid_until')::timestamptz then raise exception'pilot_closed';end if;
 local_time:=now()at time zone(c.value->>'timezone');minute_n:=extract(hour from local_time)::int*60+extract(minute from local_time)::int;
 if not(c.value->'weekdays'@>jsonb_build_array(extract(isodow from local_time)::int))or minute_n<(c.value->>'open_minute')::int or minute_n>=(c.value->>'close_minute')::int then raise exception'pilot_closed';end if;
 -- Scheduled orders need a separately reviewed operational plan; no unapproved overnight carry-over.
 if new.scheduled_for is not null then raise exception'pilot_scheduled_unavailable';end if;
 if new.lat is null or new.lng is null or new.lat<(c.value->>'min_lat')::double precision or new.lat>(c.value->>'max_lat')::double precision or new.lng<(c.value->>'min_lng')::double precision or new.lng>(c.value->>'max_lng')::double precision then raise exception'pilot_region';end if;
 perform pg_advisory_xact_lock(hashtextextended('pilot:admission-capacity',0));
 select count(*)into active_n from pilot_private.admissions a join orders o on o.id=a.order_id where o.status in('pending','preparing','ready','pickedup');
 if active_n>=(c.value->>'max_active')::int then raise exception'pilot_capacity';end if;
 select count(*)into daily_n from pilot_private.admissions a where(a.at at time zone(c.value->>'timezone'))::date=local_time::date;
 if daily_n>=(c.value->>'daily_orders')::int then raise exception'pilot_daily_limit';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.trg_loyalty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_paid numeric; v_pts int; v_cb numeric;
begin
  if new.status = 'delivered' and old.status <> 'delivered' and new.loyalty_done_at is null then
    v_paid := greatest(0, coalesce(new.subtotal, 0) - coalesce(new.discount, 0) - coalesce(new.promo_discount, 0) - coalesce(new.points_value, 0));
    v_pts := ceil(v_paid * coalesce((select earn_per_tjs from stores where id = new.store_id), loyalty_setting('loyalty_earn_per_tjs')) - 0.000001)::int;   -- fractions in favour of the customer
    if v_pts > 0 then
      insert into loyalty_lots(user_id, points, points_left, expires_at, order_id, kind)
      values (new.customer_id, v_pts, v_pts, now() + make_interval(days => loyalty_setting('loyalty_expiry_days')::int), new.id, 'earn')
      on conflict (order_id) where kind = 'earn' do nothing;
      insert into loyalty_ledger(user_id, points, kind, order_id) values (new.customer_id, v_pts, 'earn', new.id);
    end if;
    v_cb := round(v_paid * coalesce((select cashback_pct from stores where id = new.store_id), loyalty_setting('cashback_pct')) / 100, 2);   -- the restaurant's own % (it pays it)
    if v_cb > 0 then
      insert into wallet_entries(user_id, amount, kind, order_id, note) values (new.customer_id, v_cb, 'cashback', new.id, null)
      on conflict (order_id) where kind = 'cashback' do nothing;
    end if;
    new.points_earned := greatest(v_pts, 0); new.cashback := greatest(v_cb, 0); new.loyalty_done_at := now();
  end if;
  if new.status in ('rejected', 'cancelled') and old.status not in ('rejected', 'cancelled')
     and coalesce(new.points_used, 0) > 0 and new.points_returned_at is null then
    insert into loyalty_lots(user_id, points, points_left, expires_at, order_id, kind)
    values (new.customer_id, new.points_used, new.points_used, now() + make_interval(days => loyalty_setting('loyalty_expiry_days')::int), new.id, 'return')
    on conflict (order_id) where kind = 'return' do nothing;
    insert into loyalty_ledger(user_id, points, kind, order_id) values (new.customer_id, new.points_used, 'return', new.id);
    new.points_returned_at := now();
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION return_private.guard_case_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c return_private.cases;
begin
  select * into c from return_private.cases where order_id = old.id;
  if found and (
    (new.store_id, new.driver_id, new.customer_id) is distinct from (old.store_id, old.driver_id, old.customer_id)
    or (c.cancelled_at is not null and new.status <> 'cancelled')
  ) then raise exception 'return_order_protected'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION fulfillment_private.guard_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a fulfillment_private.order_approvals;internal_write boolean;ox text;
begin
 select * into a from fulfillment_private.order_approvals where order_id=old.id;
 internal_write:=coalesce(current_setting('talabot.approval_write',true),'')=old.id::text or coalesce(current_setting('talabot.order_building',true),'')=old.id::text;
 select xmin::text into ox from orders where id=old.id;
 if not internal_write and (a.order_id is not null or ox<>pg_current_xact_id()::text)then
  if row(new.total,new.subtotal,new.wallet_used,new.points_used,new.points_value,new.address,new.lat,new.lng)
   is distinct from row(old.total,old.subtotal,old.wallet_used,old.points_used,old.points_value,old.address,old.lat,old.lng)then
   raise exception 'order_change_requires_confirmation';end if;
  if new.prep_time is distinct from old.prep_time and old.prep_time is not null
   and coalesce(a.state,'legacy')<>'awaiting_merchant'
   and not(a.state='checkout_accepted'and a.merchant_at is null and old.status='pending'and new.prep_time<=old.prep_time) then raise exception 'order_change_requires_confirmation';end if;
 end if;
 if a.state in('awaiting_merchant','awaiting_customer') and
  ((new.status is distinct from old.status and new.status in('preparing','ready','pickedup','delivered'))
   or(new.driver_id is distinct from old.driver_id and new.driver_id is not null))then raise exception 'customer_confirmation_required';end if;
 return new;
end $function$
